// Learn reusable analysis rules: run the anatomy and its tests on authorised samples, keep the fingerprints of functions whose role was
// CONFIRMED, drop any fingerprint that was ever refuted or confirmed for two different roles, and record provenance.
//   node tools/custom/learn.mjs [--write]
// Samples: tests/corpus/obfuscated/** (generated by this project in isolation from open-source tools) and local/corpus/** when present
// (third-party scripts read as text; only fingerprints and hashes are stored, never content).
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { anatomy, testHypotheses } from '../../src/custom/anatomy.js';
import { evaluatePass } from '../../src/passes/evaluate.js';
import { unwrapWrapper } from '../../src/passes/structure.js';
import { tryReaders } from '../../src/custom/analyze.js';
import { fingerprint } from '../../src/custom/rules.js';
import { parse } from '../../src/core/parser.js';
import { walk } from '../../src/core/walk.js';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const write = process.argv.includes('--write');
const files = [];
const scan = (d) => { if (!fs.existsSync(d)) return; for (const f of fs.readdirSync(d)) { const p = path.join(d, f); if (fs.statSync(p).isDirectory()) scan(p); else if (f.endsWith('.lua')) files.push(p); } };
scan(path.join(root, 'tests', 'corpus', 'obfuscated'));
scan(path.join(root, 'local', 'corpus'));

const byFp = new Map();
const seen = new Set();
let tested = 0;
for (const f of files) {
  const src = fs.readFileSync(f, 'latin1');
  if (src.length > 400_000) continue;
  const sha = crypto.createHash('sha256').update(src).digest('hex');
  if (seen.has(sha)) continue;
  seen.add(sha);
  let a;
  try { a = anatomy(src); } catch { continue; }
  if (!a.ok || !a.hypotheses.some((h) => h.role)) continue;
  tested++;
  try { testHypotheses(a, src, { evaluate: (ast) => { unwrapWrapper(ast); return evaluatePass(ast, { sandbox: { enabled: true } }); }, readers: tryReaders }); } catch { continue; }
  // the shape sequences, for near matches later
  const ast = parse(src);
  const seqs = new Map();
  walk(ast, (n) => { if (n.type === 'Func') { const fp = fingerprint(n); seqs.set(fp.hash, fp.seq); } return undefined; });
  const group = path.relative(root, f).split(path.sep).slice(0, -1).join('/');
  for (const h of a.hypotheses) {
    if (!h.role || !['confirmed', 'refuted'].includes(h.test.status)) continue;
    const fn = a.functions.find((x) => `fn${x.id}:${h.role}` === h.id);
    if (!fn) continue;
    const e = byFp.get(fn.fingerprint) || { fingerprint: fn.fingerprint, roles: new Set(), confirmations: 0, refutations: 0, samples: new Set(), groups: new Set(), seq: seqs.get(fn.fingerprint) };
    e.roles.add(h.role);
    if (h.test.status === 'confirmed') e.confirmations++; else e.refutations++;
    e.samples.add(sha.slice(0, 16));
    e.groups.add(group);
    byFp.set(fn.fingerprint, e);
  }
}
const rules = [];
const rejected = { refuted: 0, ambiguousRole: 0 };
for (const e of byFp.values()) {
  if (e.refutations) { rejected.refuted++; continue; }
  if (e.roles.size !== 1) { rejected.ambiguousRole++; continue; }
  // reusable means seen more than once: a fingerprint confirmed on a single sample is that build's own code
  if (e.confirmations < 2) { rejected.single = (rejected.single || 0) + 1; continue; }
  rules.push({ fingerprint: e.fingerprint, role: [...e.roles][0], confirmations: e.confirmations, samples: [...e.samples].slice(0, 20), groups: [...e.groups].sort(), firstSeen: new Date().toISOString().slice(0, 10), seq: e.seq ? e.seq.slice(0, 600) : null });
}
rules.sort((a, b) => b.confirmations - a.confirmations);
const out = { description: 'Fingerprints of functions whose role was confirmed by a test (evaluator or VM reader) on authorised samples; built by tools/custom/learn.mjs. A fingerprint ever refuted, confirmed for two roles, or confirmed on only one sample is not kept.', samplesTested: tested, rejected, rules };
if (write) fs.writeFileSync(path.join(root, 'data', 'research', 'learned-rules.json'), JSON.stringify(out));
console.log({ samplesTested: tested, rules: rules.length, rejected, byRole: rules.reduce((m, r) => (m[r.role] = (m[r.role] || 0) + 1, m), {}), multiGroup: rules.filter((r) => r.groups.length > 1).map((r) => `${r.role}:${r.groups.join('|')}`).slice(0, 12) });
